
'use client';

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuLabel, DropdownMenuSeparator, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { Button } from '@/components/ui/button';
import { MoreHorizontal, ListFilter, Search, ClipboardCheck } from 'lucide-react';
import { useRouter } from 'next/navigation';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { cn } from '@/lib/utils';
import type { VariantProps } from 'class-variance-authority';
import { format, parseISO } from 'date-fns';
import { useToast } from '@/hooks/use-toast';
import { supabase } from '@/lib/supabase/client';

// Define the structure of an application from Supabase
export interface StoredApplication {
  id: string;
  type: string;
  applicant_name: string;
  status: string;
  created_at: string;
  data: Record<string, any>;
  user_id?: string;
}

type ApplicationStatus = 'Pending' | 'Approved' | 'Rejected' | 'Processing';

const badgeVariantsForStatus = ({ status }: { status: ApplicationStatus }) => {
  return {
    variant: (
      status === 'Approved' ? 'default' :
      status === 'Rejected' ? 'destructive' :
      status === 'Pending' ? 'secondary' :
      status === 'Processing' ? 'outline' :
      'default'
    ) as "default" | "destructive" | "secondary" | "outline" | null | undefined,
  };
};

interface StatusBadgeProps extends VariantProps<typeof badgeVariantsForStatus> {
  status: ApplicationStatus;
  className?: string;
}

const StatusBadge: React.FC<StatusBadgeProps> = ({ status, className }) => {
  const { variant } = badgeVariantsForStatus({ status });
  return <Badge variant={variant} className={cn("capitalize", className)}>{status}</Badge>;
};


export default function StageApprovalsPage() {
  const router = useRouter();
  const { toast } = useToast();
  const [applications, setApplications] = useState<StoredApplication[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<ApplicationStatus | 'All'>('All');
  
  const loadApplications = React.useCallback(async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('applications')
        .select('*')
        .eq('type', 'Stage Approval Application')
        .order('created_at', { ascending: false });
        
      if (error) throw error;
      setApplications(data as StoredApplication[]);
    } catch (error) {
      console.error("Error fetching stage approval applications from Supabase:", error);
      toast({
        title: "Error",
        description: "Failed to load stage approval applications from the database.",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  }, [toast]);

  useEffect(() => {
    loadApplications();
  }, [loadApplications]);

  const handleViewDetails = (appId: string) => {
    router.push(`/admin/applications/${appId}`);
  };

  const handleStatusChange = async (appId: string, newStatus: 'Approved' | 'Rejected') => {
     try {
        const { error } = await supabase
            .from('applications')
            .update({ status: newStatus })
            .eq('id', appId);

        if (error) throw error;
        
        setApplications(prevApps => 
            prevApps.map(app => 
                app.id === appId ? { ...app, status: newStatus } : app
            )
        );

        toast({
            title: `Application ${newStatus}`,
            description: `The application (ID: ${appId}) has been marked as ${newStatus}.`
        });
    } catch (error) {
        console.error("Error updating status:", error);
        toast({
            title: 'Error',
            description: 'Could not update the application status in the database.',
            variant: 'destructive',
        });
    }
  };

  const filteredApplications = applications.filter(app => {
    const termMatch = searchTerm.trim() === '' || 
        app.applicant_name.toLowerCase().includes(searchTerm.toLowerCase()) || 
        app.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (app.data?.originalPermitId || '').toLowerCase().includes(searchTerm.toLowerCase());
    
    const statusMatch = statusFilter === 'All' || app.status === statusFilter;

    return termMatch && statusMatch;
  });

  return (
    <div className="space-y-8">
      <Card>
        <CardHeader>
          <div className="flex items-center gap-3">
            <ClipboardCheck className="h-6 w-6 text-primary" />
            <div>
              <CardTitle>Stage Approval Applications</CardTitle>
              <CardDescription>Manage all submitted stage approval requests for construction projects.</CardDescription>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          <div className="flex items-center justify-between gap-4 mb-6">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input 
                placeholder="Search by applicant, ID, or permit ID..." 
                className="pl-10" 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="outline" className="gap-2">
                  <ListFilter className="h-4 w-4" />
                  Filter ({statusFilter})
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                <DropdownMenuLabel>Filter by Status</DropdownMenuLabel>
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={() => setStatusFilter('All')}>All</DropdownMenuItem>
                <DropdownMenuItem onClick={() => setStatusFilter('Pending')}>Pending</DropdownMenuItem>
                <DropdownMenuItem onClick={() => setStatusFilter('Approved')}>Approved</DropdownMenuItem>
                <DropdownMenuItem onClick={() => setStatusFilter('Rejected')}>Rejected</DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
          
          <div className="border rounded-md">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Application ID</TableHead>
                  <TableHead>Applicant</TableHead>
                  <TableHead>Original Permit ID</TableHead>
                  <TableHead>Date Submitted</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {loading ? (
                    <TableRow>
                        <TableCell colSpan={6} className="h-24 text-center">
                            Loading stage approval applications...
                        </TableCell>
                    </TableRow>
                ) : filteredApplications.length > 0 ? (
                  filteredApplications.map((app) => (
                    <TableRow key={app.id}>
                      <TableCell className="font-medium text-xs">{app.id}</TableCell>
                      <TableCell>{app.applicant_name}</TableCell>
                       <TableCell className="font-medium text-xs">{app.data.originalPermitId || 'N/A'}</TableCell>
                      <TableCell>{app.created_at ? format(parseISO(app.created_at), 'dd/MM/yyyy') : 'N/A'}</TableCell>
                      <TableCell>
                        <StatusBadge status={app.status as ApplicationStatus} />
                      </TableCell>
                      <TableCell className="text-right">
                         <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" className="h-8 w-8 p-0">
                              <span className="sr-only">Open menu</span>
                              <MoreHorizontal className="h-4 w-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            <DropdownMenuLabel>Actions</DropdownMenuLabel>
                            <DropdownMenuItem onClick={() => handleViewDetails(app.id)}>
                              View Details
                            </DropdownMenuItem>
                            <DropdownMenuSeparator />
                            <DropdownMenuItem onClick={() => handleStatusChange(app.id, 'Approved')}>Approve</DropdownMenuItem>
                            <DropdownMenuItem onClick={() => handleStatusChange(app.id, 'Rejected')}>Reject</DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  ))
                ) : (
                  <TableRow>
                    <TableCell colSpan={6} className="h-24 text-center">
                      No stage approval applications found.
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}
